INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 119901, 302, 450, 0, 0, "2025/12/31 11:59:59", "みやこ", 1, 119901, 3, 0, 119901, 2.17, 1, "【物理】中衛で、味方をプリンで強化する幽霊聖少女。\n物理攻撃力と物理クリティカルアップのプリンパワーの\nフィールドで自分のスキルも強化し、猛攻を繰り出す。", 0, 1, 1, 119901, "ミヤコ（クリスマス）", "2025/12/21 12:00:00", 0, 14);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 120001, 190, 450, 0, 0, "2026/03/31 11:59:59", "しずる", 1, 120001, 3, 0, 120001, 2.375, 5, "【物理】前衛で猛攻から味方を守護する闇のお姉ちゃん。\nバトル開始時の行動不能無効スキルで周囲の味方を守り、\n範囲を束縛するスキルで敵を牽制し、戦況を一変する。", 0, 1, 5, 120001, "シズル（ノワール）", "2026/03/16 10:00:00", 0, 6);
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 0, 0, 0, 0, "2030/12/31 15:00:00", "いお", 0, 120101, 3, 0, 120101, 0, 7, "", 0, 0, 7, 0, "イオ（ノワール）", "2015/04/01 15:00:00", 0, 0);
