INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 191301, 850, 450, 0, 0, "2030/12/31 15:00:00", "かずまさ", 1, 191301, 1, 0, 191301, 2.22, 6, "【物理】皆から愛される漁師町のポンコツ漁師。\nユニオンバーストは強力なスタン効果を持つが、\n自身のＨＰが50%以下では尻もちをついてしまう。\n\n・通常攻撃とユニオンバーストを駆使して戦う。", 0, 1, 6, 191301, "カズマサ", "2015/04/01 15:00:00", 0, 0);
